function Contador() {
  const [n, setN] = useState(0);
  const sumar = useCallback(() => setN(n + 1), []);
  return h("button", { onClick: sumar }, String(n));
}
// render inicial y dos clics sobre el botón

function Contador() {
  const [n, setN] = useState(1);
  const ref = useRef(0);
  const anterior = ref.current;
  ref.current = n;
  return h("p", {}, anterior + "->" + n);
}
// render inicial y después un clic que hace setN(n + 1)

function useContador(inicial) {
  const [n, setN] = useState(inicial);
  return { n, sumar: () => setN((x) => x + 1) };
}
function Contador() {
  const { n } = useContador(1);
  return h("p", {}, n);
}
console.log(renderToString(h(Contador, {})));

